from common import *
a=dict(np.load(DATA/'validation_rutas_proyectadas2014.npz'));b=dict(np.load(DATA/'validation_ruta_preferida.npz'));g=dict(np.load(DATA/'geometria_validation.npz'));assert np.array_equal(a['row'],b['row']) and np.array_equal(a['row'],g['row']);true=g['X'][:,1:15].reshape(-1,7,2)
